def handle(ctx, payload, trigger):
    """Tag the parent event when a new IP indicator is marked to_ids."""
    if not payload.get("to_ids"):
        return

    event_uuid = payload.get("event_uuid")
    if not event_uuid:
        return

    ctx.log("tagging", event_uuid, "for", payload.get("value"))
    ctx.tag_event(event_uuid, "workflow:state=\"triage\"")
